script:
(function () {
  'use strict';
  // Savings account projection, month by month. The APY is turned into a monthly growth rate,
  //   i = (1 + APY)^(1/12) - 1,
  // so a full year with no deposits grows by exactly the APY. If the rate is entered as an interest
  // rate compounded n times a year, APY = (1 + r/n)^n - 1 first. Monthly deposits land at the start
  // or end of each month and can rise by a set percentage at the start of each new year. Tax on each
  // year's interest is paid from the balance at year end.
  // Checked in Node (five.test.js): $10,000 at 4% APY for 1 year = $10,400.00; for 5 years =
  // $12,166.53 (1.04^5); 4% compounded monthly = 4.074% APY; $250/month at 0% for 5 years = $15,000;
  // $100/month end-of-month at 6% compounded monthly for 10 years = $16,387.93 (textbook annuity
  // 100 x (1.005^120 - 1)/0.005); $10,000 at 4% APY, 1 year, 24% tax = $10,304.00.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var OUTPUTS = ['svEnd', 'svDeposits', 'svInterest', 'svInitialOut', 'svAdded', 'svTaxOut', 'svApy', 'svLastMonth', 'svLastDeposit'];

  // --- calc start
  function toApy(rate, type) {
    if (type === 'apy') return rate;
    var n = parseInt(type, 10);
    return Math.pow(1 + rate / n, n) - 1;
  }

  function project(o) {
    var i = Math.pow(1 + o.apy, 1 / 12) - 1, bal = o.initial, deposit = o.monthly, added = 0,
        interest = 0, tax = 0, yDep = 0, yInt = 0, lastInt = 0, rows = [];
    for (var m = 1; m <= o.years * 12; m++) {
      if (m > 1 && (m - 1) % 12 === 0) deposit *= 1 + o.increase;
      if (o.begin) bal += deposit;
      lastInt = bal * i; bal += lastInt;
      if (!o.begin) bal += deposit;
      added += deposit; yDep += deposit; yInt += lastInt; interest += lastInt;
      if (m % 12 === 0) {
        var t = yInt * o.tax;
        bal -= t; tax += t;
        rows.push({ year: m / 12, dep: yDep, int: yInt, tax: t, bal: bal });
        yDep = 0; yInt = 0;
      }
    }
    return { balance: bal, added: added, interest: interest, tax: tax, lastInt: lastInt, lastDeposit: deposit, rows: rows };
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toFixed(3).replace(/\.?0+$/, '') + '%'; }

  function fail(msg) {
    var error = document.getElementById('svError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('svSchedule').innerHTML = '';
  }

  function update() {
    var initial = num('svInitial'), monthly = num('svMonthly'), rate = num('svRate'), years = num('svYears'),
        increase = num('svIncrease'), tax = num('svTax');
    var type = document.getElementById('svRateType').value, begin = document.getElementById('svTiming').value === 'begin';
    document.getElementById('svError').hidden = true;
    if ([initial, monthly, rate, years, increase, tax].some(isNaN)) return fail('Fill in every field with a number (use 0 where it does not apply).');
    if (initial < 0 || monthly < 0) return fail('The opening balance and deposit cannot be negative.');
    if (initial + monthly <= 0) return fail('Enter an opening balance, a monthly deposit or both.');
    if (rate < 0 || rate > 50) return fail('Enter a rate from 0 to 50%.');
    if (years < 1 || years > 60 || years !== Math.floor(years)) return fail('Enter a whole number of years from 1 to 60.');
    if (increase < 0 || increase > 50) return fail('Enter a yearly deposit increase from 0 to 50%.');
    if (tax < 0 || tax > 100) return fail('Enter a tax rate from 0 to 100%.');

    var apy = toApy(rate / 100, type);
    var r = project({ initial: initial, monthly: monthly, apy: apy, years: years, increase: increase / 100, tax: tax / 100, begin: begin });
    if (!isFinite(r.balance) || r.balance > 1e15) return fail('That result is too large to show. Try smaller numbers.');
    document.getElementById('svEnd').textContent = money.format(r.balance);
    document.getElementById('svDeposits').textContent = money.format(initial + r.added);
    document.getElementById('svInterest').textContent = money.format(r.interest);
    document.getElementById('svInitialOut').textContent = money.format(initial);
    document.getElementById('svAdded').textContent = money.format(r.added);
    document.getElementById('svTaxOut').textContent = money.format(r.tax);
    document.getElementById('svApy').textContent = pct(apy);
    document.getElementById('svLastMonth').textContent = money.format(r.lastInt);
    document.getElementById('svLastDeposit').textContent = money.format(r.lastDeposit);
    document.getElementById('svSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.dep) + '</td><td>' + money.format(row.int) +
             '</td><td>' + money.format(row.tax) + '</td><td>' + money.format(row.bal) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('svForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
